// ─── BALISTICA ──────────────────────────────────────────────
function dragG1(m){
  if(m<0.8) return 0.119+0.0141*m;
  if(m<1.0) return 0.247+0.155*(m-0.8);
  if(m<1.2) return 0.505-0.179*(m-1.0);
  return 0.327-0.060*(m-1.2);
}
function airDensity(t,p,h){
  const T=t+273.15,P=p*100;
  const Pv=(h/100)*6.1078*Math.exp(17.27*t/(t+237.3))*100;
  return (P-Pv)/(287.058*T)+Pv/(461.495*T);
}
function solveDrop(dist,V0,BC,t,p,h){
  const rhoF=airDensity(t,p,h)/1.225;
  let x=0,y=0,vx=V0,vy=0;
  while(x<dist){
    const s=Math.min(0.5,dist-x);
    const v=Math.sqrt(vx*vx+vy*vy);
    const Cd=dragG1(v/340),dt=s/vx,aD=-0.5*rhoF*Cd/BC*v;
    vx+=aD*(vx/v)*dt; vy+=(aD*(vy/v)-9.81)*dt; x+=s; y+=vy*dt;
  }
  return y*1000; // mm, negative = cade
}

// ─── INTERPOLAZIONE V0 / TEMPERATURA ────────────────────────
function interpolateV0(profile, currentTemp){
  const tbl = (profile.v0Table||[]).filter(e=>e.v0>0).sort((a,b)=>a.temp-b.temp);
  if(tbl.length===0) return profile.BC ? 320 : 320; // fallback
  if(tbl.length===1) return tbl[0].v0;
  // clamp agli estremi
  if(currentTemp<=tbl[0].temp) return tbl[0].v0;
  if(currentTemp>=tbl[tbl.length-1].temp) return tbl[tbl.length-1].v0;
  // linear interpolation
  const lo=tbl.findLast(e=>e.temp<=currentTemp);
  const hi=tbl.find(e=>e.temp>currentTemp);
  const t=(currentTemp-lo.temp)/(hi.temp-lo.temp);
  return lo.v0+t*(hi.v0-lo.v0);
}

// ─── SOLVER COMPLETO con scope height ───────────────────────
function computeDot(profile, sensors){
  const {distance,cant,pitch,riflHdg,windSpd,windDir,calHdg,temp,pres,hum,v0meas}=sensors;
  if(!distance||distance<5) return null;

  const V0_interp = interpolateV0(profile, temp);
  const V0 = v0meas>100 ? v0meas : V0_interp;
  const scopeH_mm = (profile.scopeHeight_cm||6.5)*10; // cm → mm
  const ssf = profile.ssfElev||1.0;

  // Drop assoluto dal bore (mm, negativo)
  const drop_d  = solveDrop(distance, V0, profile.BC, temp, pres, hum);
  const drop_z  = solveDrop(profile.zero, V0, profile.BC, temp, pres, hum);

  // Retta di collimazione (LOS): parte da +scopeH_mm sul bore, converge al bersaglio zero
  // y_LOS(d) = scopeH_mm + (drop_z - scopeH_mm) * (d / zero)
  const y_LOS_d = scopeH_mm + (drop_z - scopeH_mm)*(distance/profile.zero);

  // Holdover: quanto il dot deve spostarsi in su (positivo = proiettile sotto LOS)
  const holdover_mm = (y_LOS_d - drop_d) * ssf;

  // Correzione cant e pitch
  const holdover_adj = holdover_mm * Math.cos(pitch*Math.PI/180);
  const cR = cant*Math.PI/180;
  const dV = holdover_adj*Math.cos(cR);
  const dH = holdover_adj*Math.sin(cR);

  // Vento
  const wAbs = (windDir+calHdg)%360;
  const wRel  = ((wAbs-riflHdg)+360)%360;
  const cw = windSpd*Math.sin(wRel*Math.PI/180);
  const tof = distance/(V0*0.72);
  const lag = (distance/V0)-tof;
  const wDrift = cw*lag*1000*(profile.ssfWind||1.0);

  const dropMil = dV/distance;
  const windMil = (dH+wDrift)/distance;
  const mppx = 50/128;

  return {
    px:Math.max(2,Math.min(126,Math.round(64+windMil/mppx))),
    py:Math.max(2,Math.min(62,Math.round(32+dropMil/mppx))),
    dropMil, windMil, tof, cw, V0,
    dropMoa:dropMil*3.437, windMoa:windMil*3.437,
    v0Interp:V0_interp, v0Source:v0meas>100?"cronografo":"interpolata",
  };
}

// ─── OLED CANVAS ────────────────────────────────────────────
function OLEDCanvas({dot,sensors,mode}){
  const ref=useRef(null);
  useEffect(()=>{
    const c=ref.current; if(!c) return;
    const ctx=c.getContext("2d");
    const W=256,H=128,S=2;
    ctx.clearRect(0,0,W*S,H*S);
    ctx.save(); ctx.scale(S,S);
    ctx.fillStyle="#001a0d"; ctx.fillRect(0,0,W,H);
    ctx.strokeStyle="#0a3a20"; ctx.lineWidth=0.3;
    for(let x=0;x<W;x+=16){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
    for(let y=0;y<H;y+=16){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
    const cx=128,cy=64;
    ctx.strokeStyle="#1D9E7599"; ctx.lineWidth=0.8;
    ctx.beginPath();ctx.moveTo(cx,0);ctx.lineTo(cx,H);ctx.stroke();
    ctx.beginPath();ctx.moveTo(0,cy);ctx.lineTo(W,cy);ctx.stroke();
    ctx.strokeStyle="#1D9E7555"; ctx.lineWidth=0.5;
    [10,20,30,40].forEach(d=>{
      ctx.beginPath();ctx.moveTo(cx-4,cy+d);ctx.lineTo(cx+4,cy+d);ctx.stroke();
      ctx.beginPath();ctx.moveTo(cx-4,cy-d);ctx.lineTo(cx+4,cy-d);ctx.stroke();
      ctx.beginPath();ctx.moveTo(cx+d,cy-3);ctx.lineTo(cx+d,cy+3);ctx.stroke();
      ctx.beginPath();ctx.moveTo(cx-d,cy-3);ctx.lineTo(cx-d,cy+3);ctx.stroke();
    });
    ctx.strokeStyle="#ffffff33"; ctx.lineWidth=0.8;
    ctx.beginPath();ctx.arc(cx,cy,8,0,Math.PI*2);ctx.stroke();
    ctx.beginPath();ctx.arc(cx,cy,3,0,Math.PI*2);ctx.stroke();
    if(dot){
      ctx.strokeStyle="#E24B4A44"; ctx.lineWidth=0.4; ctx.setLineDash([2,2]);
      ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(dot.px*2,dot.py*2);ctx.stroke();
      ctx.setLineDash([]);
      ctx.shadowColor="#E24B4A"; ctx.shadowBlur=8;
      ctx.fillStyle="#E24B4A";
      ctx.beginPath();ctx.arc(dot.px*2,dot.py*2,3,0,Math.PI*2);ctx.fill();
      ctx.shadowBlur=0;
      ctx.fillStyle="#FF8080";
      ctx.beginPath();ctx.arc(dot.px*2,dot.py*2,1.2,0,Math.PI*2);ctx.fill();
      if(mode===1){
        ctx.fillStyle="#1D9E75"; ctx.font="9px 'Courier New'";
        ctx.fillText(sensors.distance>0?sensors.distance.toFixed(0)+"m":"--",2,10);
        ctx.fillText(dot.dropMil.toFixed(2)+"M",2,H-2);
        ctx.fillText(dot.windMil.toFixed(2)+"M",W-38,H-2);
        ctx.fillText(dot.V0.toFixed(0)+(sensors.v0meas>100?"*":"~"),W/2-10,H-2);
      }
    } else {
      ctx.strokeStyle="#1D9E7566"; ctx.lineWidth=0.8;
      ctx.beginPath();ctx.moveTo(cx-6,cy);ctx.lineTo(cx+6,cy);ctx.stroke();
      ctx.beginPath();ctx.moveTo(cx,cy-6);ctx.lineTo(cx,cy+6);ctx.stroke();
      ctx.fillStyle="#1D9E75"; ctx.font="8px Arial";
      ctx.fillText("ACQUIRE?",cx-20,H-4);
    }
    ctx.restore();
  });
  return <canvas ref={ref} width={512} height={256} style={{width:256,height:128,display:"block"}}/>;
}

// ─── SENSORI ─────────────────────────────────────────────────
function useSensors(){
  const [s,setS]=useState({
    distance:0,locked:false,
    cant:0,pitch:0,riflHdg:285,
    windSpd:2.5,windDir:38,calHdg:127,
    temp:18.4,pres:1013.2,hum:62,
    v0meas:0,sim:false,t:0,
    confirm:false,confirmDist:0,
  });
  const iRef=useRef(null);
  const startSim=useCallback(()=>{
    setS(p=>({...p,sim:true}));
    iRef.current=setInterval(()=>{
      setS(p=>{
        const t=p.t+0.05;
        return {...p,t,
          cant:parseFloat((Math.sin(t*.18)*2.5+Math.cos(t*.07)*.8).toFixed(2)),
          pitch:parseFloat((Math.sin(t*.09)*3.2).toFixed(2)),
          windSpd:parseFloat(Math.max(0,2.5+Math.sin(t*.12)*1.2+Math.cos(t*.05)*.4).toFixed(2)),
          windDir:parseFloat((38+Math.sin(t*.04)*20).toFixed(1)),
          temp:parseFloat((18.4+Math.sin(t*.01)*2).toFixed(1)),
          pres:parseFloat((1013.2+Math.sin(t*.007)*3).toFixed(1)),
        };
      });
    },150);
  },[]);
  const stopSim=useCallback(()=>{ clearInterval(iRef.current); setS(p=>({...p,sim:false})); },[]);
  useEffect(()=>()=>clearInterval(iRef.current),[]);
  const acquire=(dist)=>{
    setS(p=>{
      if(!dist&&!p.distance) return p;
      const d=dist||p.distance;
      if(p.locked&&p.distance>0&&Math.abs(d-p.distance)>15) return {...p,confirm:true,confirmDist:d};
      return {...p,distance:d,locked:true,confirm:false};
    });
  };
  const confirmChange=()=>setS(p=>({...p,distance:p.confirmDist,locked:true,confirm:false}));
  const setDist=(d)=>setS(p=>({...p,distance:d}));
  const setSensor=(k,v)=>setS(p=>({...p,[k]:v}));
  return {s,startSim,stopSim,acquire,confirmChange,setDist,setSensor};
}

